"""Legacy OPP_MASTER validation rules migrated from opportunity_rules.vrl."""

from decimal import Decimal
from typing import Any


_EMPTY_VALUES = ("", None)


def _value(record: dict, field: str) -> Any:
    """Return a field value; missing and None values behave as empty strings."""
    value = record.get(field, "")
    return "" if value is None else value


def _numeric(value: Any) -> Decimal:
    """Apply VRL numeric coercion, including empty string as zero."""
    if value in _EMPTY_VALUES:
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _date_gte(left: Any, right: Any) -> bool:
    """Apply VRL ordering semantics for YYYYMMDD dates."""
    left_text = "" if left is None else str(left)
    right_text = "" if right is None else str(right)

    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Evaluate applicable opportunity rules in legacy rule-file order."""
    errors: list[dict] = []

    def fail(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": severity,
            }
        )

    stat_cd = _value(record, "STAT_CD")
    amount = _numeric(_value(record, "AMT"))
    lost_rsn = _value(record, "LOST_RSN")
    close_dt = _value(record, "CLOSE_DT")
    stage_pct = _numeric(_value(record, "STAGE_PCT"))

    if event in ("INSERT", "UPDATE"):
        # OPP-001
        if not amount >= Decimal("0"):
            fail("E3001", "Amount negative")

        # OPP-002
        if not not (stat_cd == "W" and amount == Decimal("0")):
            fail("E3002", "Won opportunity requires amount")

        # OPP-003
        if not not (stat_cd == "L" and lost_rsn == ""):
            fail("E3003", "Lost reason required")

        # OPP-004
        if not not (stat_cd == "W" and close_dt == "00000000"):
            fail("E3004", "Won opportunity requires close date")

    if event == "UPDATE":
        # OPP-005
        old_stat_cd = _value(old or {}, "STAT_CD")
        if not not (old_stat_cd == "W" and stat_cd != "W"):
            fail("E3005", "Cannot reopen a won opportunity")

    if event in ("INSERT", "UPDATE"):
        # OPP-006
        stage_is_consistent = (
            (stat_cd == "P" and stage_pct == Decimal("10"))
            or (stat_cd == "Q" and stage_pct == Decimal("25"))
            or (stat_cd == "N" and stage_pct == Decimal("60"))
            or (stat_cd == "W" and stage_pct == Decimal("100"))
            or (stat_cd == "L" and stage_pct == Decimal("0"))
        )
        if not stage_is_consistent:
            fail("E3006", "Stage percent inconsistent with status")

    if event == "INSERT":
        # OPP-007
        if not (close_dt == "00000000" or _date_gte(close_dt, today)):
            fail("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return True when at least one validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
